export type PlaceCategory =
  | 'beach'
  | 'heritage_fort'
  | 'church'
  | 'temple'
  | 'waterfall_nature'
  | 'wildlife'
  | 'quarter_market'
  | 'viewpoint_island'

export type PlaceRegion = 'North Goa' | 'South Goa' | 'Panaji & Central'

export type BeachFlag = 'safe' | 'caution' | 'danger' | 'not_applicable'

export interface PopularExperience {
  id: string
  title: string
  location: string
  rating: number
  bookings: string
  discountPercent?: number
  originalPrice?: number
  price: number
  unit: string
  image: string
  category: string
  tags?: string[]
}

export interface PlaceReview {
  id: string
  author: string
  avatar: string
  rating: number
  date: string
  comment: string
}

export interface PlaceItem {
  id: string
  slug: string
  name: string
  localName?: string
  category: PlaceCategory
  categoryLabel: string
  region: PlaceRegion
  taluka: string
  location: string
  fullAddress: string
  coordinates: {
    lat: number
    lng: number
  }
  googleMapsUrl: string
  rating: number
  reviewsCount: number
  image: string
  gallery: string[]
  description: string
  history?: string
  highlights: string[]
  bestTimeToVisit: string
  timings: string
  entryFee: string
  entryFeeDetail?: string
  beachSafety?: {
    flagStatus: BeachFlag
    flagLabel: string
    lifeguardsOnDuty: boolean
    swimZone: string
    waterSportsAvailable: boolean
    waterSportsTypes?: string[]
    tideAdvisory?: string
  }
  amenities: string[]
  travelTips: string[]
  tags: string[]
  isUnesco?: boolean
  isMustVisit?: boolean
  reviews: PlaceReview[]
}

