    description:
      'A UNESCO World Heritage Site and one of the finest exemplars of Jesuit Baroque architecture in the world. The Basilica holds the sacred sacred mortal remains of St. Francis Xavier, patron saint of Goa, encased in an intricate silver casket inside a Florentine marble mausoleum.',
