    description:
      'Perched high above the Chapora River estuary and Vagator Beach, Chapora Fort offers the most celebrated sunset vantage in Goa. Immortalized by the Bollywood cult movie "Dil Chahta Hai", its sweeping battlements embrace views from Morjim’s sandspit to Ozran’s rocky coves.',
    history:
      'Originally built by Adil Shah of Bijapur before being captured and reconstructed in red laterite stone by the Portuguese in 1717. It withstood fierce Maratha sieges under Sambhaji Maharaj in 1683.',
    highlights: [
      'Unobstructed sunset panoramic views over the Chapora estuary and Arabian sea',
      'Famous "Dil Chahta Hai" cinematic wall viewpoint',
      'Atmospheric irregular laterite battlements hugging natural hill contours',
      'Scenic 10-minute stone uphill hike from the parking base',
    ],
    bestTimeToVisit: '4:30 PM to 6:30 PM for sunset golden hour',
    timings: 'Open daily from sunrise to sunset (approx 6:00 AM – 6:30 PM)',
    entryFee: 'Free Entry',
    entryFeeDetail: 'Free access managed by the Directorate of Archives and Archaeology.',
    amenities: [
      'Paved Hillside Trail Steps',
      'Fresh Coconut & Juice Stalls at the Base',
      'Two-Wheeler & Car Parking at Base',
    ],
    travelTips: [
      'Wear sturdy sneakers as the stone incline has loose gravel that can be slippery.',
      'Head down before pitch black as the hill path has minimal lighting.',
    ],
